\set ON_ERROR_STOP on
set client_min_messages=warning;

create function pg_temp.recipe() returns jsonb language sql immutable as $$select '{"version":"sf-sdxl-recommended-v1","mode":"recommended","settings":{"resolution":[1024,1024],"enable_bucket":true,"min_bucket_reso":512,"max_bucket_reso":1024,"bucket_reso_steps":64,"train_batch_size":1,"learning_rate":0.0001,"network_module":"networks.lora","network_dim":64,"network_alpha":32,"mixed_precision":"fp16","gradient_checkpointing":true,"save_model_as":"safetensors","save_every_n_steps":200,"target_effective_samples":1200,"caption_extension":".txt","caption_model":"Salesforce/blip-image-captioning-base","trigger_suffix":"woman"}}'::jsonb$$;
create function pg_temp.quality(n int, ready boolean) returns jsonb language sql immutable as $$select jsonb_build_object('accepted_count',n,'rejected_count',0,'composition_summary',jsonb_build_object('closeup',n),'dataset_quality_score',case when ready then 90 else 55 end,'dataset_warnings',case when ready then '[]'::jsonb else '["dataset_unbalanced"]'::jsonb end,'dataset_warnings_structured',case when ready then '[]'::jsonb else '[{"type":"dataset_unbalanced","category":"quality","overridable":true}]'::jsonb end,'guidance',case when ready then '[]'::jsonb else '["Add variety"]'::jsonb end,'dataset_ready',ready,'confidence_message','reviewed selection','composition_balance','{"missing":[],"underrepresented":[],"overrepresented":[]}'::jsonb,'balance_score',case when ready then 90 else 55 end,'primary_issue',case when ready then null else 'missing_midshots' end,'secondary_issues','[]'::jsonb,'priority_guidance','[]'::jsonb,'dataset_strengths','[]'::jsonb,'shot_suggestions','[]'::jsonb,'dataset_grade',case when ready then 'A' else 'C' end,'training_prediction','bounded','confidence_signal','medium')$$;
create function pg_temp.summary(ids jsonb,ready boolean) returns jsonb language sql immutable as $$select jsonb_build_object('raw_count',jsonb_array_length(ids),'accepted_count',jsonb_array_length(ids),'rejected_count',0,'review_count',0,'needs_more_images',not ready,'missing_coverage','[]'::jsonb,'composition_summary','{}'::jsonb,'dataset_quality_score',50,'dataset_warnings','[]'::jsonb,'dataset_warnings_structured','[]'::jsonb,'guidance','[]'::jsonb,'dataset_ready',true,'confidence_message','whole attempt','composition_balance','{"missing":[],"underrepresented":[],"overrepresented":[]}'::jsonb,'balance_score',50,'primary_issue',null,'secondary_issues','[]'::jsonb,'priority_guidance','[]'::jsonb,'dataset_strengths','[]'::jsonb,'shot_suggestions','[]'::jsonb,'dataset_grade','B','training_prediction','bounded','confidence_signal','medium','analysis_version',4,'mode','dataset_doctor_quality_v1','quality_contract_version','dataset-doctor-quality-v1','rebuild_from_r2',false,'review_selection',jsonb_build_object('contract_version','dataset-doctor-review-selection-v1','image_ids',ids,'image_count',jsonb_array_length(ids),'selection_fingerprint',repeat('a',64),'evidence_fingerprint',repeat('b',64),'quality_summary',pg_temp.quality(jsonb_array_length(ids),ready),'quality_fingerprint',repeat('c',64)))$$;
create function pg_temp.payload(job uuid,lora uuid,snapshot jsonb,decision jsonb,ids jsonb) returns jsonb language sql stable as $$select jsonb_build_object('identity_id',lora::text,'dataset_doctor_job_id',job::text,'dataset_reference',jsonb_build_object('bucket','datasets','prefix','final/'||job::text),'dataset_snapshot',snapshot,'dataset_selection',jsonb_build_object('image_ids',ids,'image_count',jsonb_array_length(ids)),'dataset_training_decision',decision,'trainer_recipe',pg_temp.recipe())$$;
create function pg_temp.expect_error(expected text,statement text) returns void language plpgsql as $$begin execute statement;raise exception 'EXPECTED_FAILURE_NOT_RAISED:%',expected;exception when others then if sqlerrm not like expected||'%' then raise exception 'EXPECTED_%,GOT_%',expected,sqlerrm;end if;end$$;

-- RPC-only prompt/receipt authority.
do $$declare role_name text;t text;fn regprocedure;begin foreach t in array array['dataset_doctor_training_decision_prompts','dataset_doctor_training_decision_receipts'] loop foreach role_name in array array['anon','authenticated','service_role'] loop assert not has_table_privilege(role_name,'public.'||t,'select');assert not has_table_privilege(role_name,'public.'||t,'insert');assert not has_table_privilege(role_name,'public.'||t,'update');assert not has_table_privilege(role_name,'public.'||t,'delete');end loop;end loop;foreach fn in array array['public.prepare_dataset_training_decision_prompt(uuid,uuid,uuid,text,uuid[])'::regprocedure,'public.record_dataset_training_decision_receipt(uuid,uuid,uuid,text)'::regprocedure,'public.validate_dataset_training_decision_receipt(uuid,uuid,uuid,uuid)'::regprocedure] loop assert has_function_privilege('service_role',fn,'execute');assert not has_function_privilege('anon',fn,'execute');assert not has_function_privilege('authenticated',fn,'execute');assert not exists(select 1 from aclexplode((select proacl from pg_proc where oid=fn))a where grantee=0 and privilege_type='EXECUTE');end loop;end$$;

insert into auth.users(id) values('10000000-0000-4000-8000-000000000001');
