create temporary table ids(kind text, value jsonb);
insert into ids values ('override','["40000000-0000-4000-8000-000000000001","40000000-0000-4000-8000-000000000002","40000000-0000-4000-8000-000000000003"]'),('ready','["40000000-0000-4000-8000-000000000011","40000000-0000-4000-8000-000000000012","40000000-0000-4000-8000-000000000013"]');
insert into public.dataset_doctor_jobs(id,lora_id,user_id,status,final_r2_bucket,final_r2_prefix,summary,needs_more_images,missing_coverage) values
('30000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000001'::uuid,'10000000-0000-4000-8000-000000000001'::uuid,'ready_for_review',null,null,pg_temp.summary((select value from ids where kind='override'),false),true,'[]'),
('30000000-0000-4000-8000-000000000002'::uuid,'20000000-0000-4000-8000-000000000002'::uuid,'10000000-0000-4000-8000-000000000001'::uuid,'exported','datasets','final/30000000-0000-4000-8000-000000000002',pg_temp.summary((select value from ids where kind='ready'),true),false,'[]');
