insert into public.dataset_doctor_selections(id,job_id,image_id,lora_id,user_id,selection_type) select gen_random_uuid(),job_id,id,lora_id,user_id,'final' from public.dataset_doctor_images where job_id='30000000-0000-4000-8000-000000000002';

-- A valid selected-ready V4 authority succeeds; top-level whole-attempt readiness is irrelevant.
create temporary table ready_job as select job_id from public.submit_trainer_compute_job('10000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000002'::uuid,'ready-v4',repeat('1',64),pg_temp.payload('30000000-0000-4000-8000-000000000002'::uuid,'20000000-0000-4000-8000-000000000002',public.dataset_training_selected_authority((select summary from public.dataset_doctor_jobs where id='30000000-0000-4000-8000-000000000002')),'null',public.dataset_training_final_selection('30000000-0000-4000-8000-000000000002')),'standard','datasets','final/30000000-0000-4000-8000-000000000002');
update public.compute_jobs set state='failed',terminal_at=statement_timestamp(),safe_error_code='TEST_TERMINAL' where id=(select job_id from ready_job);

-- Unknown/malformed V4 evidence is prohibited before submission.
update public.dataset_doctor_jobs set summary=summary||'{"future_debug":true}'::jsonb where id='30000000-0000-4000-8000-000000000002';
select pg_temp.expect_error('DATASET_TRAINING_PROHIBITED',format('select * from public.submit_trainer_compute_job(%L,%L,%L,%L,%L::jsonb,%L,%L,%L)','10000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000002'::uuid,'unknown-v4',repeat('2',64),pg_temp.payload('30000000-0000-4000-8000-000000000002'::uuid,'20000000-0000-4000-8000-000000000002'::uuid,'{}','null',(select value from ids where kind='ready'))::text,'standard','datasets','final/30000000-0000-4000-8000-000000000002'));
update public.dataset_doctor_jobs set summary=pg_temp.summary((select value from ids where kind='ready'),true) where id='30000000-0000-4000-8000-000000000002';

-- Exact reviewed not-ready selection: prompt, immutable shown evidence, export, receipt, job link.
create temporary table prompt_one as select * from public.prepare_dataset_training_decision_prompt('10000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000001'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'decision-one',array(select jsonb_array_elements_text((select value from ids where kind='override'))::uuid));
do $$declare p public.dataset_doctor_training_decision_prompts;begin select x.* into p from public.dataset_doctor_training_decision_prompts x join prompt_one t on t.prompt_id=x.id;assert p.dataset_snapshot=public.dataset_training_selected_authority((select summary from public.dataset_doctor_jobs where id=p.dataset_doctor_job_id));assert p.warning_snapshot=p.dataset_snapshot#>'{review_selection,quality_summary}';assert p.shown_at=p.created_at;assert (select prompt_id from public.prepare_dataset_training_decision_prompt(p.user_id,p.lora_id,p.dataset_doctor_job_id,p.decision_idempotency_key,array(select jsonb_array_elements_text(p.selected_image_ids)::uuid)))=p.id;end$$;
select pg_temp.expect_error('DATASET_TRAINING_DECISION_STALE',$$select * from public.prepare_dataset_training_decision_prompt('10000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000001'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'wrong-selection',array['40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000099']::uuid[])$$);
update public.dataset_doctor_jobs set status='exported',final_r2_bucket='datasets',final_r2_prefix='final/30000000-0000-4000-8000-000000000001' where id='30000000-0000-4000-8000-000000000001';
insert into public.dataset_doctor_selections(id,job_id,image_id,lora_id,user_id,selection_type) select gen_random_uuid(),job_id,id,lora_id,user_id,'final' from public.dataset_doctor_images where job_id='30000000-0000-4000-8000-000000000001';
create temporary table receipt_one as select * from public.record_dataset_training_decision_receipt('10000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000001'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'decision-one');
create temporary table override_payload as select pg_temp.payload(j.id,j.lora_id,public.dataset_training_selected_authority(j.summary),jsonb_build_object('receipt_id',r.id::text,'decision',r.decision,'contract_version',r.decision_contract_version,'warning_fingerprint',r.warning_fingerprint,'dataset_snapshot_fingerprint',r.dataset_snapshot_fingerprint),public.dataset_training_final_selection(j.id)) payload from public.dataset_doctor_jobs j join public.dataset_doctor_training_decision_receipts r on r.dataset_doctor_job_id=j.id where r.decision_idempotency_key='decision-one';
create temporary table override_job as select job_id from public.submit_trainer_compute_job('10000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000001'::uuid,'override-one',repeat('3',64),(select payload from override_payload),'standard','datasets','final/30000000-0000-4000-8000-000000000001');
do $$begin assert (select training_job_id from public.dataset_doctor_training_decision_receipts where decision_idempotency_key='decision-one')=(select job_id from override_job);assert (select job_id from public.submit_trainer_compute_job('10000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000001'::uuid,'override-one',repeat('3',64),(select payload from override_payload),'standard','datasets','final/30000000-0000-4000-8000-000000000001'))=(select job_id from override_job);end$$;

-- New explicit decision key creates a distinct future retrain receipt.
update public.compute_jobs set state='failed',terminal_at=statement_timestamp(),safe_error_code='TEST_TERMINAL' where id=(select job_id from override_job);
create temporary table prompt_two as select * from public.prepare_dataset_training_decision_prompt('10000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000001'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'decision-two',array(select jsonb_array_elements_text((select value from ids where kind='override'))::uuid));
create temporary table receipt_two as select * from public.record_dataset_training_decision_receipt('10000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000001'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'decision-two');
do $$begin assert (select receipt_id from receipt_one)<>(select receipt_id from receipt_two);begin update public.dataset_doctor_training_decision_receipts set warning_snapshot='{}';raise exception 'mutable';exception when others then assert sqlerrm='DATASET_TRAINING_DECISION_EVIDENCE_IMMUTABLE';end;end$$;
